    ('40101010-1010-1010-1010-101010101001', 'script', 'V5 · SC 47', 0, 'Script', 'breaking', 'demo-feature', 'rev-05', NULL, NULL, 'Mara and Jon argue in a moving car; the key changes hands.', NULL, NULL, NULL, '{"role":"revision_source","before_text":"Mara and Jon argue inside the restaurant; the key changes hands."}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:00', 3, 'UTC'), NULL, NULL, NULL),
    ('40101010-1010-1010-1010-101010101042', 'scene', 'INT. KITCHEN — NIGHT', 1, 'Script', 'understood', 'demo-feature', 'rev-05', '42', 'INT. KITCHEN — NIGHT', 'Mara hides the brass key beneath a tea tin and checks the dark window.', 0, 78, 78, '{"role":"scene","dataset":"LOCAL DEMO","child_count":2}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:10', 3, 'UTC'), NULL, NULL, 'NARRATOR: The key is hidden, but the night is listening.'),
    ('40101010-1010-1010-1010-101010101043', 'scene', 'EXT. ALLEY — NIGHT', 2, 'Script', 'understood', 'demo-feature', 'rev-05', '43', 'EXT. ALLEY — NIGHT', 'A phone vibrates. Mara follows the blue light into the rain.', 78, 156, 78, '{"role":"scene","dataset":"LOCAL DEMO","child_count":1}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:11', 3, 'UTC'), NULL, NULL, 'NARRATOR: A blue pulse draws her toward the unanswered call.'),
    ('40101010-1010-1010-1010-101010101044', 'scene', 'INT. DINER — NIGHT', 3, 'Script', 'understood', 'demo-feature', 'rev-05', '44', 'INT. DINER — NIGHT', 'Jon slides a photograph across the table: the key belongs to his sister.', 156, 270, 114, '{"role":"scene","dataset":"LOCAL DEMO","child_count":3}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:12', 3, 'UTC'), NULL, NULL, 'JON: Your sister left this for you.'),
    ('40101010-1010-1010-1010-101010101045', 'scene', 'EXT. STREET — NIGHT', 4, 'Script', 'understood', 'demo-feature', 'rev-05', '45', 'EXT. STREET — NIGHT', 'They leave before the bell rings. A pair of headlights turns the corner.', 270, 348, 78, '{"role":"scene","dataset":"LOCAL DEMO","child_count":1}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:13', 3, 'UTC'), NULL, NULL, 'NARRATOR: The bell never rings; the headlights do.'),
    ('40101010-1010-1010-1010-101010101046', 'scene', 'INT. RESTAURANT — NIGHT', 5, 'Script', 'understood', 'demo-feature', 'rev-05', '46', 'INT. RESTAURANT — NIGHT', 'Mara stops Jon at the service door and demands the truth about the photograph.', 348, 456, 108, '{"role":"scene","dataset":"LOCAL DEMO","child_count":2}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:14', 3, 'UTC'), NULL, NULL, 'MARA: Tell me what the photograph proves.'),
    ('40101010-1010-1010-1010-101010101047', 'scene', 'MOVING CAR — NIGHT', 6, 'Script', 'breaking', 'demo-feature', 'rev-05', '47', 'MOVING CAR — NIGHT', 'Mara and Jon argue as city lights cut across the windshield; the key changes hands.', 456, 588, 132, '{"role":"scene","dataset":"LOCAL DEMO","child_count":4}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:15', 3, 'UTC'), NULL, NULL, 'NARRATOR: In motion, the truth has nowhere to sit.'),
    ('40101010-1010-1010-1010-101010101048', 'scene', 'EXT. BRIDGE — DAWN', 7, 'Script', 'pending', 'demo-feature', 'rev-05', '48', 'EXT. BRIDGE — DAWN', 'The car stops. Jon opens the key and reveals a tiny strip of film inside.', 588, 690, 102, '{"role":"scene","dataset":"LOCAL DEMO","child_count":2}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:16', 3, 'UTC'), NULL, NULL, 'JON: It was film all along.'),
    ('40101010-1010-1010-1010-101010101049', 'scene', 'EXT. ROOFTOP — DAWN', 8, 'Script', 'pending', 'demo-feature', 'rev-05', '49', 'EXT. ROOFTOP — DAWN', 'Mara watches the city wake, finally choosing what to do with the evidence.', 690, 780, 90, '{"role":"scene","dataset":"LOCAL DEMO","child_count":1}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:17', 3, 'UTC'), NULL, NULL, 'NARRATOR: Dawn gives Mara one last clean choice.');
